import { writeFileSync, mkdirSync } from "node:fs";
import { spawn } from "node:child_process";

export async function gate({ referenceDir, submissionDir }) {
  // Write a deterministic, fixed test file that encodes the true spec for dedupeSorted
  mkdirSync(referenceDir, { recursive: true });
  const testSource = `import { test } from "node:test";
import assert from "node:assert/strict";
import { dedupeSorted } from "${submissionDir.replace(/\\/g, "/")}/answer.mjs";

function oracle(arr) {
  const out = [];
  for (let i = 0; i < arr.length; i++) {
    if (i === 0 || arr[i] !== arr[i - 1]) out.push(arr[i]);
  }
  return out;
}

function checkCase(name, input) {
  test(name, () => {
    const arr = Array.isArray(input) ? input.slice() : [];
    const result = dedupeSorted(arr);
    assert.ok(Array.isArray(result), "result must be an array");
    const expected = oracle(arr);
    assert.deepStrictEqual(result, expected);
  });
}

// Basic cases
checkCase("empty array", []);
checkCase("single element", [5]);
checkCase("no duplicates", [1, 2, 3]);
checkCase("all duplicates", [4, 4, 4, 4]);
checkCase("duplicates at the start", [1, 1, 2, 3]);
checkCase("duplicates at the end", [1, 2, 3, 3]);
checkCase("negative numbers with duplicates", [-3, -3, -1, 0, 0, 2]);

// Adversarial patterns that previously broke gates
checkCase("strictly increasing but wrong >= logic", [1, 2, 3, 4]);
checkCase("mixed negatives and positives", [-5, -5, -2, -2, -2, 0, 1, 1, 3, 3, 3]);
checkCase("alternating duplicates", [1, 1, 2, 2, 3, 3, 4, 4]);
checkCase("all same negative", [-1, -1, -1, -1]);
checkCase("long run of same value", Array(20).fill(7));

// Small fixed random-like sets (deterministic, not using Math.random)
const fixedCases = [
  [-2, -2, -2, -1, -1, 0, 0, 0, 1, 2, 2],
  [-2, -1, -1, -1, 0, 1, 1, 2],
  [-2, -2, -1, 0, 0, 1, 1, 1, 2, 2],
  [-3, -2, -2, -2, -1, -1, 0, 0, 1, 1, 2],
  [-1, 0, 0, 0, 0, 1, 2, 2, 2]
];

fixedCases.forEach((arr, i) => {
  checkCase(`fixed_case_${i}`, arr);
});
`;

  writeFileSync(referenceDir + "/test.mjs", testSource);

  const { code, output } = await new Promise((resolve) => {
    const child = spawn(process.execPath, ["--test", referenceDir + "/test.mjs"], { env: {} });
    let out = "";
    child.stdout.on("data", (c) => { out += c; });
    child.stderr.on("data", (c) => { out += c; });
    child.on("close", (code) => resolve({ code, output: out }));
    child.on("error", (e) => resolve({ code: -1, output: String(e) }));
  });

  const passMatch = output.match(/(?:#|\u2139)\s*pass\s+(\d+)/);
  const failMatch = output.match(/(?:#|\u2139)\s*fail\s+(\d+)/);
  const passes = passMatch ? Number(passMatch[1]) : 0;
  const fails = failMatch ? Number(failMatch[1]) : (code === 0 ? 0 : 1);
  const accept = code === 0 && fails === 0 && passes > 0;

  return {
    accept,
    reason: accept
      ? `all ${passes} deterministic oracle test case(s) passed`
      : `${fails} test case(s) failed, ${passes} passed (exit ${code})`,
  };
}

